function groupDays() {
  const groups = new Map();
  chapters.forEach(c => {
    if (!groups.has(c.date)) groups.set(c.date, []);
    groups.get(c.date).push(c);
  });
  return [...groups.entries()].sort((a,b)=>a[0].localeCompare(b[0]));
}
