function finishRouteIntro(){
 clearRouteTimers();routeSkip.hidden=true;routeContinue.hidden=false;
}
function showRouteIntro(date,route){
 clearRouteTimers();
 welcomeView.hidden=true;daysView.hidden=true;chaptersView.hidden=true;panel.hidden=true;routeIntroView.hidden=false;
 routeDayLabel.textContent=chapters.find(c=>c.date===date)?.dateLabel||'THE NORTH · A JOURNEY';
 routeTitle.textContent=route.title;routeSubtitle.textContent=route.subtitle;
 routeSceneHeading.innerHTML='<span>SEVERNÉ ANGLICKO</span><strong>Miesta dnešnej cesty</strong>';
 const mapNote=document.getElementById('route-map-note');
 if(mapNote) mapNote.textContent='Schematická mapa – nie je v mierke.';
 routeSteps.innerHTML='<div class="route-sequence">'+route.sequence.map((name,i)=>'<span>'+String(i+1).padStart(2,'0')+' '+name+'</span>').join('<i aria-hidden="true">→</i>')+'</div>';
 routeContinue.hidden=true;routeSkip.hidden=true;animateView(routeIntroView);
 renderBlankMap(route);
}
function openSelectedChapter(){
 const chapter=chapters.find(c=>c.date===currentDate&&isUnlocked(c));
 if(chapter)openChapter(chapter.id);
}
function revealDays(){
 clearRouteTimers();
 routeIntroView.hidden=true;welcomeView.hidden=true;chaptersView.hidden=true;panel.hidden=true;daysView.hidden=false;animateView(daysView);
 const available=groupDays().filter(([,items])=>items.some(isUnlocked));
 if(!available.length){
  const next=groupDays().find(([,items])=>!items.some(isUnlocked));
  const dateText=next?next[1][0].dateLabel.replace(/^[^·]+·\s*/,''):'';
  daysList.innerHTML='<p class="empty-note">Ďalší deň sa otvorí '+dateText+'.</p>';return;
 }
 daysList.innerHTML=available.map(([date,items],i)=>{
  const chapter=items[0];
  const stopName=['Prvé zastavenie','Druhé zastavenie','Tretie zastavenie','Štvrté zastavenie'][i]||'Ďalšie zastavenie';
  return '<button class="day-row" type="button" data-date="'+date+'"><span class="day-index">'+String(i+1).padStart(2,'0')+'</span><span class="day-meta"><span class="day-name">'+stopName+'</span><span class="day-date">'+chapter.dateLabel.replace(/^[^·]+·\s*/,'')+'</span></span><span class="day-arrow" aria-hidden="true">→</span></button>';
 }).join('');
 daysList.querySelectorAll('.day-row').forEach(el=>el.addEventListener('click',()=>showDay(el.dataset.date)));
}
function showDays(){revealDays();}
function showDay(date){
 currentDate=date;
 const chapter=chapters.find(c=>c.date===date&&isUnlocked(c));
 const route=mapRoutes[date];
 if(!chapter||!route)return;
 showRouteIntro(date,route);
}
function animateView(view) {
  view.classList.remove('view-enter');
  void view.offsetWidth;
  view.classList.add('view-enter');
}
function removeFurtherReading(root) {
  root.querySelectorAll('h3').forEach(heading => {
    if (/^na ďalšie čítanie$/i.test(heading.textContent.trim())) {
      const list = heading.nextElementSibling;
      heading.remove();
      if (list && list.tagName === 'UL') list.remove();
    }
  });
}
function placeEditorialImages(chapter, root) {
  const visuals = chapter.visuals || [];
  if (!visuals.length) return;
  visuals.forEach((visual, index) => {
    const figure = document.createElement('figure');
    figure.className = `article-figure ${index % 2 === 0 ? 'figure--right' : 'figure--left'}`;
    const image = document.createElement('img');
    image.src = visual.src;
    image.alt = visual.alt || '';
    image.loading = index === 0 ? 'eager' : 'lazy';
    image.decoding = 'async';
    image.sizes = '(max-width: 600px) 48vw, 320px';
    image.addEventListener('error', () => figure.remove(), { once: true });
    figure.appendChild(image);
    const caption = document.createElement('figcaption');
    const description = document.createElement('span');
    description.className = 'image-caption';
    description.textContent = visual.caption || '';
    const credit = document.createElement(visual.href ? 'a' : 'span');
    credit.className = 'image-credit';
    credit.textContent = visual.credit || '';
    if (visual.href) { credit.href = visual.href; credit.target = '_blank'; credit.rel = 'noopener'; }
    if (visual.creditHref) { credit.href = visual.creditHref; credit.target = '_blank'; credit.rel = 'noopener'; }
    caption.append(description, credit);
    if (visual.creditHref && visual.href) {
      const source = document.createElement('a');
      source.href = visual.href;
      source.target = '_blank';
      source.rel = 'noopener';
      source.textContent = 'zdroj';
      source.className = 'image-credit';
      caption.append(' · ', source);
    }
    if (visual.licenseHref) {
      const license = document.createElement('a');
      license.href = visual.licenseHref;
      license.target = '_blank';
      license.rel = 'noopener';
      license.textContent = visual.licenseText || 'licencia';
      license.className = 'image-credit';
      caption.append(' · ', license);
    }
    figure.appendChild(caption);
    const paragraphs = [...root.querySelectorAll('p')];
    const textAnchor = visual.afterText ? paragraphs.find(p => p.textContent.toLocaleLowerCase('sk').includes(visual.afterText.toLocaleLowerCase('sk'))) : null;
    if (textAnchor) textAnchor.insertAdjacentElement('afterend', figure);
    else {
      const headings = [...root.querySelectorAll('h3')];
      const heading = visual.afterHeading ? headings.find(h => h.textContent.trim().toLocaleLowerCase('sk').includes(visual.afterHeading.toLocaleLowerCase('sk'))) : null;
      const anchor = heading ? heading.nextElementSibling : null;
      if (anchor && anchor.tagName === 'P') anchor.insertAdjacentElement('afterend', figure);
      else {
      const paragraphs = [...root.querySelectorAll('p')];
      const fallback = paragraphs[Math.min(paragraphs.length - 1, Math.max(0, Math.round((index + 1) * paragraphs.length / (visuals.length + 1)) - 1))];
      if (fallback) fallback.insertAdjacentElement('afterend', figure);
      }
    }
  });
}
function openChapter(id) {
  const c = chapters.find(x=>x.id===id);
  if (!c || !isUnlocked(c)) return;
  document.getElementById('reading-day').textContent = c.dateLabel;
  document.getElementById('reading-title').textContent = c.title;
  document.getElementById('reading-deck').textContent = c.deck;
  const words = (c.body.replace(/<[^>]*>/g,' ').match(/\S+/g)||[]).length;
  document.getElementById('reading-time').textContent = `${Math.max(3,Math.ceil(words/190))} MIN ČÍTANIA`;
  const articleBody = document.getElementById('reading-body');
  articleBody.innerHTML = c.body;
  removeFurtherReading(articleBody);
  placeEditorialImages(c, articleBody);
  document.getElementById('reading-visual').innerHTML = '';
  document.getElementById('reading-curiosity').textContent = c.curiosity;
  welcomeView.hidden = true;
  routeIntroView.hidden = true;
  daysView.hidden = true;
  chaptersView.hidden = true;
  panel.hidden = false;
  animateView(panel);
  window.scrollTo({top:0,behavior:'smooth'});
}
document.getElementById('continue-button').addEventListener('click',showDays);
routeSkip.addEventListener('click',finishRouteIntro);
document.getElementById('route-back').addEventListener('click',revealDays);
routeContinue.addEventListener('click',openSelectedChapter);
document.getElementById('days-back').addEventListener('click',showWelcome);
document.getElementById('chapters-back').addEventListener('click',()=>{
  chaptersView.hidden = true;
  daysView.hidden = false;
  animateView(daysView);
  window.scrollTo({top:0,behavior:'smooth'});
});
document.getElementById('back-button').addEventListener('click',()=>{
  const route=mapRoutes[currentDate];
  if(route)showRouteIntro(currentDate,route);
  window.scrollTo({top:0,behavior:'smooth'});
});
if ('serviceWorker' in navigator && location.protocol.startsWith('http')) {
  navigator.serviceWorker.register('./sw.js').catch(()=>{});
}
